  "gts.lg.p1": "Mueve el jugador 1",
  "gts.lg.p2": "Mueve el jugador 2",
  "gts.lg.leaf": "Final: pago de 1 sobre pago de 2",
  "gts.lg.best": "Mejor jugada en ese nodo",
